package com.bank.hold.service;

import com.bank.hold.model.Interval;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Inserts a new hold into a sorted non-overlapping schedule, merging overlaps.
public class HoldScheduleService {
    private static final Logger log = Logger.getLogger(HoldScheduleService.class.getName());

    public List<Interval> insertHold(List<Interval> schedule, Interval newHold) {
        List<Interval> result = new ArrayList<>();
        if (schedule == null) {
            schedule = new ArrayList<>();
        }
        int n = schedule.size();
        int i = 0;

        // Phase 1: copy holds that end before the new hold starts.
        while (i < n && schedule.get(i).getEnd() < newHold.getStart()) {
            result.add(schedule.get(i));
            final Interval kept = schedule.get(i);
            log.fine(() -> "Phase 1 keep " + kept);
            i++;
        }

        // Phase 2: merge all holds overlapping the new hold.
        int newStart = newHold.getStart();
        int newEnd = newHold.getEnd();
        while (i < n && schedule.get(i).getStart() <= newEnd) {
            newStart = Math.min(newStart, schedule.get(i).getStart());
            newEnd = Math.max(newEnd, schedule.get(i).getEnd());
            final Interval absorbed = schedule.get(i);
            final int ns = newStart, ne = newEnd;
            log.fine(() -> "Phase 2 merge " + absorbed + " → [" + ns + "," + ne + "]");
            i++;
        }
        result.add(new Interval(newStart, newEnd));

        // Phase 3: copy the remaining holds that start after the merged hold.
        while (i < n) {
            result.add(schedule.get(i));
            final Interval tail = schedule.get(i);
            log.fine(() -> "Phase 3 keep " + tail);
            i++;
        }
        log.info(() -> "Schedule after inserting " + newHold + " = " + result);
        return result;
    }
}
