package com.bank.hold;

import com.bank.hold.model.Account;
import com.bank.hold.model.Interval;
import com.bank.hold.service.HoldScheduleService;

import java.math.BigDecimal;
import java.util.Date;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class InsertIntervalDemo {
    private static final Logger log = Logger.getLogger(InsertIntervalDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        HoldScheduleService service = new HoldScheduleService();

        List<Interval> rajeshSchedule = List.of(
                new Interval(1, 2), new Interval(3, 5),
                new Interval(6, 7), new Interval(8, 10), new Interval(12, 16));
        Interval rajeshNew = new Interval(4, 9);
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId()
                + ") schedule = " + rajeshSchedule + ", new = " + rajeshNew);
        List<Interval> r1 = service.insertHold(rajeshSchedule, rajeshNew);
        log.info(() -> rajesh.getHolderName() + " result = " + r1);

        List<Interval> priyaSchedule = List.of(new Interval(1, 3), new Interval(6, 9));
        Interval priyaNew = new Interval(2, 5);
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId()
                + ") schedule = " + priyaSchedule + ", new = " + priyaNew);
        List<Interval> r2 = service.insertHold(priyaSchedule, priyaNew);
        log.info(() -> priya.getHolderName() + " result = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
